// A single function template using a universal reference to handle both lvalues and rvalues.
template<typename Container, typename Index>
auto& authAndAccess(Container&& c, Index i)
{
  // authenticateUser();
  // std::forward preserves the value category (lvalue/rvalue) of the container
  return std::forward<Container>(c)[i];
}

std::vector<int> v = {10, 20};

// 1. Pass an lvalue: c is an lvalue, so we get an lvalue reference back.
int& item1 = authAndAccess(v, 0);

// 2. Pass an rvalue: c is an rvalue (a temporary).
// The return type would be an rvalue reference, but we can't bind it to a non-const lvalue ref.
// auto&& captures it correctly.
auto&& item2 = authAndAccess(std::vector<int>{30, 40}, 1);
